CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_name text NOT NULL DEFAULT 'HEXENSE LABS PRIVATE LIMITED', brand_name text NOT NULL DEFAULT 'Six Sense Mobility', logo_url text, header_logo_url text, address text, website text, default_email text, phone text, footer_text text, document_branding jsonb NOT NULL DEFAULT '{}'::jsonb, default_classification text NOT NULL DEFAULT 'Internal', timezone text NOT NULL DEFAULT 'Asia/Kolkata', date_format text NOT NULL DEFAULT 'DD MMM YYYY', financial_year_start_month smallint NOT NULL DEFAULT 4, default_currency text NOT NULL DEFAULT 'INR', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role; ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view organization" ON public.organizations FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage organization" ON public.organizations FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, code text, description text, parent_department_id uuid REFERENCES public.departments(id) ON DELETE SET NULL, department_lead_user_id uuid, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, color text, icon text, document_code_enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name), UNIQUE(code));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.departments TO authenticated; GRANT ALL ON public.departments TO service_role; ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view departments" ON public.departments FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage departments" ON public.departments FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE, employee_code text UNIQUE, first_name text, last_name text, display_name text, official_email text UNIQUE, personal_email text, phone text, designation text, primary_department_id uuid REFERENCES public.departments(id) ON DELETE SET NULL, reporting_manager_user_id uuid, department_lead_user_id uuid, employment_status text NOT NULL DEFAULT 'ACTIVE' CHECK (employment_status IN ('INVITED','ACTIVE','SUSPENDED','EXITED')), date_of_joining date, profile_photo_url text, current_work_location text, default_role_id uuid, onboarding_completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role; ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users view employee directory" ON public.employees FOR SELECT TO authenticated USING (auth.uid() = user_id OR public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins manage employees" ON public.employees FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.employee_departments (employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE, department_id uuid NOT NULL REFERENCES public.departments(id) ON DELETE CASCADE, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(employee_id, department_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.employee_departments TO authenticated; GRANT ALL ON public.employee_departments TO service_role; ALTER TABLE public.employee_departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users view employee department memberships" ON public.employee_departments FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage employee departments" ON public.employee_departments FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.access_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text, is_system boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.access_roles TO authenticated; GRANT ALL ON public.access_roles TO service_role; ALTER TABLE public.access_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view roles" ON public.access_roles FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage access roles" ON public.access_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, module_key text NOT NULL, label text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.permissions TO authenticated; GRANT ALL ON public.permissions TO service_role; ALTER TABLE public.permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view permissions" ON public.permissions FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage permissions" ON public.permissions FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.access_role_permissions (role_id uuid NOT NULL REFERENCES public.access_roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(role_id, permission_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.access_role_permissions TO authenticated; GRANT ALL ON public.access_role_permissions TO service_role; ALTER TABLE public.access_role_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view role permissions" ON public.access_role_permissions FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage role permissions" ON public.access_role_permissions FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.employee_access_roles (employee_id uuid NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES public.access_roles(id) ON DELETE CASCADE, assigned_by_user_id uuid, assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(employee_id, role_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.employee_access_roles TO authenticated; GRANT ALL ON public.employee_access_roles TO service_role; ALTER TABLE public.employee_access_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users view their access roles" ON public.employee_access_roles FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.employees e WHERE e.id = employee_id AND e.user_id = auth.uid()) OR public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins manage employee access roles" ON public.employee_access_roles FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.application_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, name text NOT NULL, group_key text NOT NULL, route_path text, icon_key text, status text NOT NULL DEFAULT 'COMING_SOON' CHECK (status IN ('ENABLED','DISABLED','COMING_SOON')), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.application_modules TO authenticated; GRANT ALL ON public.application_modules TO service_role; ALTER TABLE public.application_modules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users can view modules" ON public.application_modules FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage application modules" ON public.application_modules FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, category text NOT NULL DEFAULT 'SYSTEM', title text NOT NULL, body text, target_url text, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users manage their own notifications" ON public.notifications FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Admins view all notifications" ON public.notifications FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.activity_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid, module_key text NOT NULL, entity_type text NOT NULL, entity_id uuid, action text NOT NULL, summary text NOT NULL, before_data jsonb, after_data jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.activity_log TO authenticated; GRANT ALL ON public.activity_log TO service_role; ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins can view activity log" ON public.activity_log FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin')); CREATE POLICY "Authenticated users create activity entries" ON public.activity_log FOR INSERT TO authenticated WITH CHECK (auth.uid() = actor_user_id);
CREATE TABLE public.entity_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, permalink text NOT NULL UNIQUE, qr_payload text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity_type,entity_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.entity_registry TO authenticated; GRANT ALL ON public.entity_registry TO service_role; ALTER TABLE public.entity_registry ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users view entity registry" ON public.entity_registry FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage entity registry" ON public.entity_registry FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.document_numbering_config (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, label text NOT NULL, prefix_template text NOT NULL, serial_padding smallint NOT NULL DEFAULT 3, is_active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.document_numbering_config TO authenticated; GRANT ALL ON public.document_numbering_config TO service_role; ALTER TABLE public.document_numbering_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated users view document configuration" ON public.document_numbering_config FOR SELECT TO authenticated USING (true); CREATE POLICY "Admins manage document configuration" ON public.document_numbering_config FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid, _permission_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id, 'admin') OR EXISTS (SELECT 1 FROM public.employees e JOIN public.employee_access_roles ear ON ear.employee_id=e.id JOIN public.access_role_permissions arp ON arp.role_id=ear.role_id JOIN public.permissions p ON p.id=arp.permission_id WHERE e.user_id=_user_id AND e.employment_status='ACTIVE' AND p.key=_permission_key) $$;
CREATE OR REPLACE FUNCTION public.touch_ssm_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER organizations_touch_ssm BEFORE UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at(); CREATE TRIGGER departments_touch_ssm BEFORE UPDATE ON public.departments FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at(); CREATE TRIGGER employees_touch_ssm BEFORE UPDATE ON public.employees FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at(); CREATE TRIGGER access_roles_touch_ssm BEFORE UPDATE ON public.access_roles FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at(); CREATE TRIGGER application_modules_touch_ssm BEFORE UPDATE ON public.application_modules FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at(); CREATE TRIGGER document_numbering_config_touch_ssm BEFORE UPDATE ON public.document_numbering_config FOR EACH ROW EXECUTE FUNCTION public.touch_ssm_updated_at();